//! Differential probe battery for the re1.5 port.
//!
//! Reads `scripts/re15_vectors.txt` (generated by
//! `scripts/gen_re15_vectors.py`; oracle = the reference binary's
//! `ure` module for execution cases, a standalone build of the
//! patched C sources for `dump`/`sizecode`, CPython only as a
//! cross-check recorded in the divergences report) and checks every
//! case against the Rust port. One case per line, space-separated;
//! byte strings are lowercase hex (an empty hex token is the empty
//! string). All failures are collected and reported at the end, so
//! one bad case does not hide the rest.
//!
//! The split/sub loops below replicate `vendor/micropython/extmod/
//! modre.c` (`re_split`, `re_sub_helper`) exactly — they are the
//! real caller's loops, so the battery exercises the engine the way
//! Phase D's modre port will. The replacement expansion in
//! [`expand_repl`] is a literal port of modre.c's replacement loop
//! (`\1`..`\9`, `\g<n>`, `\\`, invalid group -> IndexError).

use crate::vendor::re15::*;

const VECTORS: &str = include_str!("../../scripts/re15_vectors.txt");

fn unhex(s: &str) -> Vec<u8> {
    let mut out = Vec::with_capacity(s.len() / 2);
    let b = s.as_bytes();
    let mut i = 0;
    while i < b.len() {
        out.push(u8::from_str_radix(&s[i..i + 2], 16).unwrap());
        i += 2;
    }
    out
}

fn spans_string(caps: &[Sub]) -> String {
    let mut s = String::from("MATCH");
    for c in caps {
        match (c.start, c.end) {
            (Some(a), Some(b)) => s.push_str(&format!(" {} {}", a, b)),
            _ => s.push_str(" -1 -1"),
        }
    }
    s
}

fn run_engine(prog: &ByteProg, subj: &Subject, anchored: bool) -> Option<String> {
    let mut caps = vec![Sub::new(); prog.sub + 1];
    if recursiveloopprog_subject(prog, subj, &mut caps, anchored) {
        Some(spans_string(&caps))
    } else {
        None
    }
}

/// modre.c `re_split`, minus the object layer.
enum SplitOutcome {
    Pieces(Vec<Vec<u8>>),
    WithCaptures,
}

fn run_split(prog: &ByteProg, subj: &[u8], mut maxsplit: i64) -> SplitOutcome {
    let mut pieces: Vec<Vec<u8>> = Vec::new();
    let mut begin = 0usize;
    loop {
        let subject = Subject::new(subj, 0, begin, subj.len());
        let mut caps = vec![Sub::new(); prog.sub + 1];
        let res = recursiveloopprog_subject(prog, &subject, &mut caps, false);
        // If we didn't have a match, or had an empty match, stop.
        if !res || caps[0].start == caps[0].end {
            break;
        }
        let m0 = caps[0].start.unwrap();
        let m1 = caps[0].end.unwrap();
        pieces.push(subj[begin..m0].to_vec());
        if prog.sub > 0 {
            return SplitOutcome::WithCaptures;
        }
        begin = m1;
        if maxsplit > 0 {
            maxsplit -= 1;
            if maxsplit == 0 {
                break;
            }
        }
    }
    pieces.push(subj[begin..].to_vec());
    SplitOutcome::Pieces(pieces)
}

/// modre.c `re_sub_helper`, minus the object layer. `Err(())` is the
/// invalid-group IndexError.
fn expand_repl(repl: &[u8], subj: &[u8], caps: &[Sub], num_matches: usize) -> Result<Vec<u8>, ()> {
    let mut out: Vec<u8> = Vec::new();
    let mut i = 0usize;
    while i < repl.len() {
        if repl[i] == b'\\' {
            i += 1;
            let mut is_g_format = false;
            if repl.get(i) == Some(&b'g') && repl.get(i + 1) == Some(&b'<') {
                i += 2;
                is_g_format = true;
            }
            if repl.get(i).map_or(false, |c| c.is_ascii_digit()) {
                // Group number, decimal, wrapping u32 (C: unsigned int).
                let mut match_no: u32 = 0;
                loop {
                    match_no = match_no
                        .wrapping_mul(10)
                        .wrapping_add((repl[i] - b'0') as u32);
                    i += 1;
                    if !repl.get(i).map_or(false, |c| c.is_ascii_digit()) {
                        break;
                    }
                }
                if is_g_format && repl.get(i) == Some(&b'>') {
                    i += 1;
                }
                if match_no as usize >= num_matches {
                    return Err(());
                }
                let g = &caps[match_no as usize];
                if let (Some(s), Some(e)) = (g.start, g.end) {
                    out.extend_from_slice(&subj[s..e]);
                }
            } else if repl.get(i) == Some(&b'\\') {
                out.push(repl[i]);
                i += 1;
            }
            // Otherwise (e.g. `\n`): nothing is appended here; the
            // loop re-reads the byte as a normal character, so the
            // backslash is dropped and the byte itself is kept.
        } else {
            out.push(repl[i]);
            i += 1;
        }
    }
    Ok(out)
}

enum SubOutcome {
    Done(Vec<u8>),
    InvalidGroup,
}

fn run_sub(prog: &ByteProg, subj: &[u8], repl: &[u8], mut count: i64) -> SubOutcome {
    let mut out: Vec<u8> = Vec::new();
    let mut begin = 0usize;
    let mut any_match = false;
    loop {
        let subject = Subject::new(subj, 0, begin, subj.len());
        let mut caps = vec![Sub::new(); prog.sub + 1];
        let res = recursiveloopprog_subject(prog, &subject, &mut caps, false);
        if !res || caps[0].start == caps[0].end {
            break;
        }
        any_match = true;
        let m0 = caps[0].start.unwrap();
        let m1 = caps[0].end.unwrap();
        out.extend_from_slice(&subj[begin..m0]);
        match expand_repl(repl, subj, &caps, prog.sub + 1) {
            Ok(expanded) => out.extend_from_slice(&expanded),
            Err(()) => return SubOutcome::InvalidGroup,
        }
        begin = m1;
        if count > 0 {
            count -= 1;
            if count == 0 {
                break;
            }
        }
    }
    if !any_match {
        // Optimisation for case of no substitutions (modre.c returns
        // `where` unchanged).
        return SubOutcome::Done(subj.to_vec());
    }
    out.extend_from_slice(&subj[begin..]);
    SubOutcome::Done(out)
}

#[test]
fn probe_vectors() {
    let mut failures: Vec<String> = Vec::new();
    let mut count = 0usize;

    for (lineno, line) in VECTORS.lines().enumerate() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        count += 1;
        let f: Vec<&str> = line.split(' ').collect();
        let op = f[0];
        // Compare a rendered "got" string against the vector's
        // payload, so a mismatch prints both sides.
        let check = |got: String, want: &str, failures: &mut Vec<String>| {
            if got != want {
                failures.push(format!("line {}: {}: got {} want {}", lineno + 1, line, got, want));
            }
        };
        match op {
            "dump" => {
                let pat = unhex(f[1]);
                let want_size: usize = f[2].parse().unwrap();
                let want_dump = String::from_utf8(unhex(f[3])).unwrap();
                let size = sizecode(&pat);
                if size != Some(want_size) {
                    failures.push(format!(
                        "line {}: dump {:?}: sizecode got {:?} want Some({})",
                        lineno + 1,
                        String::from_utf8_lossy(&pat),
                        size,
                        want_size
                    ));
                }
                let mut prog = ByteProg::new();
                match compilecode(&mut prog, &pat) {
                    Ok(()) => check(dumpcode(&prog), &want_dump, &mut failures),
                    Err(e) => failures.push(format!(
                        "line {}: dump {:?}: compile failed: {:?}",
                        lineno + 1,
                        String::from_utf8_lossy(&pat),
                        e
                    )),
                }
            }
            "search" | "match" => {
                let pat = unhex(f[1]);
                let subj = unhex(f[2]);
                let want = f[3..].join(" ");
                let prog = match compile_or_fail(&pat, lineno + 1, &mut failures) {
                    Some(p) => p,
                    None => continue,
                };
                let got = run_engine(&prog, &Subject::whole(&subj), op == "match")
                    .unwrap_or_else(|| "NOMATCH".to_string());
                check(got, &want, &mut failures);
            }
            "matchpos" => {
                // matchpos <m|s> <pat> <subj> <pos|-> <endpos|-> <payload>
                let anchored = f[1] == "m";
                let pat = unhex(f[2]);
                let subj = unhex(f[3]);
                let pos: Option<i64> = if f[4] == "-" { None } else { Some(f[4].parse().unwrap()) };
                let endpos: Option<i64> = if f[5] == "-" { None } else { Some(f[5].parse().unwrap()) };
                let want = f[6..].join(" ");
                let prog = match compile_or_fail(&pat, lineno + 1, &mut failures) {
                    Some(p) => p,
                    None => continue,
                };
                // modre.c clamping (re_exec_helper).
                let len = subj.len() as i64;
                let begin = match pos {
                    None => 0,
                    Some(p) => p.clamp(0, len),
                };
                let end = match endpos {
                    None => len,
                    Some(e) => {
                        if e > len {
                            len
                        } else if e < begin {
                            begin
                        } else {
                            e
                        }
                    }
                };
                let subject = Subject::new(&subj, 0, begin as usize, end as usize);
                let got = run_engine(&prog, &subject, anchored)
                    .unwrap_or_else(|| "NOMATCH".to_string());
                check(got, &want, &mut failures);
            }
            "split" => {
                let pat = unhex(f[1]);
                let subj = unhex(f[2]);
                let maxsplit: i64 = f[3].parse().unwrap();
                let want = f[4..].join(" ");
                let prog = match compile_or_fail(&pat, lineno + 1, &mut failures) {
                    Some(p) => p,
                    None => continue,
                };
                let got = match run_split(&prog, &subj, maxsplit) {
                    SplitOutcome::Pieces(pieces) => {
                        let mut s = format!("SPLIT {}", pieces.len());
                        for p in &pieces {
                            s.push_str(&format!(" {}", p.iter().map(|b| format!("{:02x}", b)).collect::<String>()));
                        }
                        // The driver prints payload.strip(); an empty
                        // piece renders as a bare space, so the
                        // vector has no trailing space either.
                        s.trim_end().to_string()
                    }
                    SplitOutcome::WithCaptures => "EXC NotImplementedError".to_string(),
                };
                check(got, &want, &mut failures);
            }
            "sub" => {
                let pat = unhex(f[1]);
                let subj = unhex(f[2]);
                let repl = unhex(f[3]);
                let sub_count: i64 = f[4].parse().unwrap();
                let want = f[5..].join(" ");
                let prog = match compile_or_fail(&pat, lineno + 1, &mut failures) {
                    Some(p) => p,
                    None => continue,
                };
                let got = match run_sub(&prog, &subj, &repl, sub_count) {
                    SubOutcome::Done(res) => {
                        // As above, the driver strips the payload; an
                        // empty result renders as "SUB" in the vector.
                        format!("SUB {}", res.iter().map(|b| format!("{:02x}", b)).collect::<String>())
                            .trim_end()
                            .to_string()
                    }
                    SubOutcome::InvalidGroup => "EXC IndexError".to_string(),
                };
                check(got, &want, &mut failures);
            }
            "compileerr" => {
                let pat = unhex(f[1]);
                let want_size = f[2];
                let mut prog = ByteProg::new();
                if compilecode(&mut prog, &pat).is_ok() {
                    failures.push(format!(
                        "line {}: compileerr {:?}: compiled OK, want error",
                        lineno + 1,
                        String::from_utf8_lossy(&pat)
                    ));
                }
                let size = sizecode(&pat);
                let got_size = match size {
                    Some(n) => n.to_string(),
                    None => "NONE".to_string(),
                };
                if got_size != want_size {
                    failures.push(format!(
                        "line {}: compileerr {:?}: sizecode got {} want {}",
                        lineno + 1,
                        String::from_utf8_lossy(&pat),
                        got_size,
                        want_size
                    ));
                }
            }
            _ => {
                failures.push(format!("line {}: unknown op {:?}", lineno + 1, op));
            }
        }
    }

    assert!(
        failures.is_empty(),
        "{} probe case(s) run, {} failure(s):\n{}",
        count,
        failures.len(),
        failures.join("\n")
    );
    println!("probe battery: {} cases, 0 failures", count);
}

fn compile_or_fail(pat: &[u8], lineno: usize, failures: &mut Vec<String>) -> Option<ByteProg> {
    let mut prog = ByteProg::new();
    match compilecode(&mut prog, pat) {
        Ok(()) => Some(prog),
        Err(e) => {
            failures.push(format!(
                "line {}: pattern {:?} failed to compile: {:?}",
                lineno,
                String::from_utf8_lossy(pat),
                e
            ));
            None
        }
    }
}
